'use client';
import { useEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useIsoLayoutEffect, useReducedMotion, useSeconds } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { avatarInk, enter, Spin, Swap, Tip, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './agent-inbox.css';

export type InboxGroup = 'needs' | 'running' | 'done';

export interface InboxRun {
  id: string;
  /** What the run is for, like "Publish the pricing page" */
  title: string;
  /** Which agent runs it. Its first letter marks the row, and a finished run shows it under the title */
  agent: string;
  /** The mark's fill, like 'var(--dm-av-l)'. An avatar colour brings its own ink, any other colour takes white initials. Defaults to the accent */
  color?: string;
  group: InboxGroup;
  /** The line under the title: why it needs you, or what it is doing now. A finished run shows its agent instead */
  detail?: string;
  /** Marks a run that needs you because it failed: its detail turns red and it offers Retry instead of Approve */
  failed?: boolean;
  /** More on the failure, in a tooltip on its detail line */
  why?: string;
  /** How long a running run has been going, in seconds. Its clock counts on from here */
  seconds?: number;
  /** When a finished run ended, like "12m ago" */
  ended?: string;
}

export interface AgentInboxProps {
  runs: InboxRun[];
  /** Adds Approve to the runs that need you and haven't failed */
  onApprove?: (id: string) => void;
  /** Adds Retry to the runs that failed */
  onRetry?: (id: string) => void;
  /** Defaults to "Inbox". Each group shows its own count, so the head has only its mark and title */
  title?: string;
  className?: string;
}

const GROUPS: [InboxGroup, string][] = [['needs', 'Needs you'], ['running', 'Running'], ['done', 'Done']];
const clock = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;

/** Every agent run in one list, grouped as Needs you, Running and Done, with live clocks on the running ones. Approve
    starts a run that waits for you and Retry tries a failed one again; a run that changes group glides to its place. */
export function AgentInbox({ runs, onApprove, onRetry, title = 'Inbox', className }: AgentInboxProps) {
  const reduce = useReducedMotion();
  const list = useRef<HTMLDivElement>(null);
  // the inbox grows and shrinks with its rows, eased (as grow() on the site)
  const [root, inner] = useGrow();
  // Clean's one hover: a highlight that glides from run to run; a run on its way to another group keeps its own fill
  useHoverGlide(root, '.dm-aib-i', { keep: '.dm-mv' });
  // what changes after the first render plays its entrance; what is there from the start just appears
  const ready = useRef(false);
  useEffect(() => { ready.current = true; }, []);
  // one tick a second drives every running clock: each counts on from the seconds it had when it was last given
  const tick = useSeconds(runs.some(r => r.group === 'running'));
  const base = useRef(new Map<string, { s: number; at: number }>());
  const secs = (r: InboxRun) => {
    const b = base.current.get(r.id), s = r.seconds ?? 0;
    if (!b || b.s !== s) { base.current.set(r.id, { s, at: tick }); return s; }
    return b.s + tick - b.at;
  };
  for (const id of [...base.current.keys()]) if (!runs.some(r => r.id === id && r.group === 'running')) base.current.delete(id);

  // a run that changes group glides there: rows and group titles are measured after each move and eased from where
  // they were, the moving row rides above the rest, and a group that comes back fades in
  const where = useRef(new Map<string, number>());
  const groupOf = useRef(new Map<string, InboxGroup>());
  const sig = runs.map(r => r.id + ':' + r.group).join();
  useIsoLayoutEffect(() => {
    const box = list.current; if (!box) return;
    const top = box.getBoundingClientRect().top, next = new Map<string, number>();
    box.querySelectorAll<HTMLElement>('[data-k]').forEach(el => {
      const k = el.dataset.k!, y = el.getBoundingClientRect().top - top, was = where.current.get(k);
      next.set(k, y);
      if (reduce || !where.current.size) return;
      if (was === undefined) { el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 260 }); return; }
      if (Math.abs(was - y) > 1) el.animate([{ transform: `translateY(${was - y}px)` }, { transform: 'none' }], { duration: 420, easing: getComputedStyle(box).getPropertyValue('--dm-ease').trim() || 'ease' });
      const moved = groupOf.current.get(k), now = runs.find(r => r.id === k)?.group;
      if (moved && now && moved !== now) { el.classList.add('dm-mv'); setTimeout(() => el.classList.remove('dm-mv'), 440); }
    });
    where.current = next;
    groupOf.current = new Map(runs.map(r => [r.id, r.group]));
  }, [sig]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div data-dm="" ref={root} className={cx('dm-aib dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-aib-h">
        {/* the head has a neutral mark in a tile, the column the agents' marks sit in; each group carries its own count */}
        <span className="dm-aib-hi" aria-hidden="true"><Icon name="mail" /></span>
        <b>{title}</b>
      </div>
      <div ref={list}>
        {GROUPS.map(([g, name]) => {
          const rows = runs.filter(r => r.group === g);
          // a group with nothing in it goes away
          if (!rows.length) return null;
          return (
            <section key={g} className="dm-aib-g" aria-label={name}>
              <div className="dm-aib-gh" data-k={'h:' + g}><span>{name}</span><span className="dm-n">{rows.length}</span></div>
              <div className="dm-aib-gl" role="list">
                {rows.map(r => {
                  const col = r.color ?? 'var(--dm-accent)', fail = g === 'needs' && !!r.failed;
                  const detail = g === 'done' ? r.agent : r.detail ?? '';
                  return (
                    <div key={r.id} data-k={r.id} className={cx('dm-aib-i', fail && 'dm-fail')} role="listitem">
                      <span className="dm-aib-av" style={{ background: col, color: avatarInk(col) ?? (r.color ? '#fff' : 'var(--dm-on-accent)') }} aria-hidden="true">{r.agent.charAt(0)}</span>
                      <span className="dm-aib-t">
                        <b>{r.title}</b>
                        {fail && r.why ? <Tip label={r.why}><span><Swap>{detail}</Swap></span></Tip> : <Swap>{detail}</Swap>}
                      </span>
                      <Right key={g + (fail ? '!' : '')} run={r} group={g} fail={fail} secs={g === 'running' ? secs(r) : 0} fresh={ready.current} onApprove={onApprove} onRetry={onRetry} />
                    </div>
                  );
                })}
              </div>
            </section>
          );
        })}
      </div>
      </div>
    </div>
  );
}

function Right({ run, group, fail, secs, fresh, onApprove, onRetry }: { run: InboxRun; group: InboxGroup; fail: boolean; secs: number; fresh: boolean; onApprove?: (id: string) => void; onRetry?: (id: string) => void }) {
  // it plays its entrance when it mounts after the first render, as a run changes group, and not again on each clock tick
  const [e] = useState(() => fresh ? enter() : undefined);
  let body = null;
  if (group === 'needs') {
    if (fail && onRetry) body = <button type="button" className="dm-pill dm-sm dm-aib-go" aria-label={`Retry ${run.title}`} onClick={() => onRetry(run.id)}><Icon name="refresh" size="xs" />Retry</button>;
    else if (!fail && onApprove) body = <button type="button" className="dm-pill dm-primary dm-sm dm-aib-go" aria-label={`Approve ${run.title}`} onClick={() => onApprove(run.id)}>Approve</button>;
  } else if (group === 'running') body = <><Spin /><span className="dm-num">{clock(secs)}</span></>;
  else body = <><span className="dm-ok"><Icon name="ok" size="xs" /></span><span>{run.ended}</span></>;
  return <span className={cx('dm-aib-r', e?.className)} style={e?.style}>{body}</span>;
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agent inbox ---------- */
/* every run in one list, grouped by what it needs: Needs you, Running, Done. A run glides to its new group when it moves.
   The card sits on two columns (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column
   with the agents' marks under it, and the title and each run's words 12px after it; the buttons and the clocks end on the
   content's right edge, and each row shares one centre line. Each group's name and count is a section label on the
   content's left edge, over the marks, so it never reads as another run's words. A run's row is not a button, so it has no
   hover fill, and one that failed keeps its red words and Retry with no red band behind them; a run that moves glides
   without lifting */
.dm-aib{width:100%;max-width:440px;margin:0 auto;padding:16px 16px 6px}
.dm-aib-h{display:flex;align-items:center;gap:12px;padding:0 0 4px}
.dm-aib-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:var(--dm-r-sm);color:var(--dm-fg2);background:var(--dm-chip)}
.dm-aib-h b{flex:1;min-width:0;font-weight:500;font-size:14px;line-height:20px}
.dm-aib-g{display:flex;flex-direction:column}
.dm-aib-gh{display:flex;align-items:center;gap:var(--dm-s-2);padding:12px 0 4px;font-size:12px;line-height:18px;color:var(--dm-muted)}
.dm-aib-gh .dm-n{font-variant-numeric:tabular-nums}
.dm-aib-gl{display:flex;flex-direction:column}
.dm-aib-i{display:flex;align-items:center;gap:12px;padding:8px 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .16s}
.dm-aib-i.dm-mv{position:relative;z-index:1;background:var(--dm-surface)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-aib :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-aib .dm-ib:active,:root [data-style="clean"] .dm-aib .dm-ib:active,:root [data-style="clean"].dm-aib .dm-ib:active{transform:none}
.dm-aib-av{width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;font-size:11px;font-weight:500}
.dm-aib-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-aib-t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-aib-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-aib-i.dm-fail .dm-aib-t span{color:var(--dm-bad)}
.dm-aib-r{display:flex;align-items:center;gap:6px;flex:none;font-size:12.5px;color:var(--dm-fg2)}
.dm-aib-r .dm-spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-aib-r .dm-ok{color:var(--dm-ok);display:grid}
.dm-aib-i.dm-fail .dm-aib-r .dm-pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* Clean (owner, 18 Nov): the head's mark has a hairline like the other tiles; the done ticks are the vivid mark green,
   never the darker text green; Retry is the secondary button as Clean draws it everywhere (its tokens) */
:root[data-style="clean"] .dm-aib-hi,:root [data-style="clean"] .dm-aib-hi,:root [data-style="clean"].dm-aib-hi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
/* a group's name is the list's section label (owner, 18 Nov), in the smaller muted label type of a menu's group heading, so
   it never reads as a run's description; a little more room above it sets the groups apart */
:root[data-style="clean"] .dm-aib-gh,:root [data-style="clean"] .dm-aib-gh,:root [data-style="clean"].dm-aib-gh{padding-top:16px;font-size:11.5px;line-height:16px}
:root[data-style="clean"] .dm-aib-r .dm-ok,:root [data-style="clean"] .dm-aib-r .dm-ok,:root [data-style="clean"].dm-aib-r .dm-ok{color:var(--dm-ok-mark)}
:root[data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill,:root [data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill,:root [data-style="clean"].dm-aib-i.dm-fail .dm-aib-r .dm-pill{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover,:root [data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover,:root [data-style="clean"].dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover,:root [data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover,:root [data-style="clean"].dm-aib-i.dm-fail .dm-aib-r .dm-pill:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:active,:root [data-style="clean"] .dm-aib-i.dm-fail .dm-aib-r .dm-pill:active,:root [data-style="clean"].dm-aib-i.dm-fail .dm-aib-r .dm-pill:active{box-shadow:var(--dm-btn2-press)}
